SELECT type, path FROM cls WHERE path LIKE '/Game/Sparta/%' AND (path LIKE '%Armor%' OR path LIKE '%Cosmetic%' OR path LIKE '%Skin%' OR path LIKE '%Glow%' OR path LIKE '%Harden%' OR path LIKE '%StoneForm%' OR path LIKE '%Petrif%') AND (path LIKE '%/BP_%' OR path LIKE '%/BPC_%' OR path LIKE '%/WP_%' OR path LIKE '%/GE_%' OR path LIKE '%/GA_%' OR path LIKE '%/ABP_%' OR path LIKE '%/VAR_%') ORDER BY path
